import os, sys; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import Bank
B = Bank('127.', 1150, own='cte_73.jsonl')
def H(code, d, q, right, wrong, e): return B.hand(code, d, q, right, wrong, e)

# ---- 489 Clinical Medical Assisting ----
H('489.d.1.A',3,"In a busy clinic, the staff member who takes vital signs, rooms patients, and assists the provider with exams is the:","medical assistant",["pharmacist","surgeon","radiologist"],"Medical assistants support clinical care.")
H('489.d.1.A',4,"A medical assistant may work in settings such as physician offices, urgent care centers, and:","outpatient clinics",["airports","restaurants","stadiums"],"MAs work in ambulatory settings.")
H('489.d.1.B',3,"Tasks a medical assistant is legally allowed to perform are defined by the state's:","scope of practice",["lunch policy","parking map","dress code"],"Scope of practice sets limits.")
H('489.d.1.B',4,"A medical assistant who is asked to interpret a patient's lab results and diagnose a condition should decline because this is outside the:","scope of practice",["lunch hour","uniform policy","break schedule"],"Diagnosis belongs to licensed providers.")
H('489.d.1.C',3,"In the healthcare hierarchy, a medical assistant reports to a supervising physician or:","clinic manager",["patient","visitor","vendor"],"Chain of command guides authority.")
H('489.d.1.C',4,"Following the chain of command means that a concern about patient care is first brought to the:","immediate supervisor",["newspaper","insurance company","neighbor"],"Use proper channels.")
H('489.d.1.D',3,"A group of professionals such as nurses, therapists, and physicians who work together to plan patient care is an interdisciplinary:","team",["parade","band","store"],"Teams combine expertise.")
H('489.d.1.D',4,"A dietitian on an interdisciplinary team contributes by planning the patient's:","nutrition",["surgery schedule","parking","billing codes"],"Each member has a role.")
H('489.d.2.A',3,"When a patient's blood pressure reading is much higher than normal, the medical assistant should report it to the provider both orally and in:","writing",["a song","a cartoon","a text to a friend"],"Abnormal findings are documented.")
H('489.d.2.A',4,"When reporting an abnormal result, the medical assistant should state the patient's name, the finding, and the:","time it was taken",["lunch order","coat color","clinic's address"],"Include time and facts.")
H('489.d.2.B',3,"Speaking at a slow pace in simple words to a patient with limited health knowledge helps with:","understanding",["confusion","delay","billing"],"Clear communication aids understanding.")
H('489.d.2.B',4,"Repeating back what a patient says to confirm the meaning is a technique called:","active listening",["interrupting","ignoring","assuming"],"Active listening verifies meaning.")
H('489.d.2.C',3,"A patient who is upset about a long wait should be met with calm, respectful words and:","an apology",["laughter","silence","blame"],"Empathy defuses frustration.")
H('489.d.2.C',4,"A patient who does not make eye contact because of cultural norms should be treated with:","respect",["suspicion","impatience","teasing"],"Cultural sensitivity matters.")
H('489.d.2.D',3,"Two coworkers disagree about covering a shift. A cooperative way to resolve it is to find a solution that works for:","both people",["only the boss","nobody","the loudest voice"],"Cooperation seeks mutual solutions.")
H('489.d.2.D',4,"A conflict-resolution technique where each side gives up something to reach agreement is:","compromise",["avoidance","competition","denial"],"Compromise is mutual concession.")
H('489.d.2.E',3,"A medical assistant explaining the importance of washing hands to prevent the flu is providing patient:","education",["billing","scheduling","coding"],"Patient education improves health.")
H('489.d.2.E',4,"After teaching a patient how to use an inhaler, the medical assistant checks understanding by asking the patient to:","demonstrate it back",["leave quickly","sign a form only","guess"],"Teach-back confirms learning.")
H('489.d.3.A',3,"The ethical principle of doing no harm is called:","non-maleficence",["beneficence","autonomy","justice"],"First, do no harm.")
H('489.d.3.A',4,"Treating all patients fairly regardless of income or background reflects the principle of:","justice",["autonomy","beneficence","fidelity"],"Justice means fairness.")
H('489.d.3.B',3,"Cloning, genetic testing, and electronic data sharing raise ethical questions about technology and patient:","privacy",["parking","fashion","advertising"],"Technology creates ethical issues.")
H('489.d.3.B',4,"A debate on whether insurance companies should use a person's genetic test results raises concerns of:","discrimination",["transportation","decoration","entertainment"],"Genetic information can be misused.")
H('489.d.3.C',3,"Failing to provide the standard of care that results in injury to a patient is:","malpractice",["donation","courtesy","delegation"],"Malpractice is negligence by a professional.")
H('489.d.3.C',4,"One element that must be proven in a negligence case is that the provider owed the patient a:","duty of care",["gift","discount","vacation"],"Duty is the first element.")
H('489.d.3.D',3,"A document listing a patient's rights to respect, privacy, and informed decisions is the Patient's:","Bill of Rights",["Menu","Directory","Calendar"],"The Patient's Bill of Rights.")
H('489.d.3.D',4,"The law that protects patient health information from being shared without permission is:","HIPAA",["OSHA","CLIA","ADA"],"HIPAA protects privacy.")
H('489.d.4.A',3,"When scheduling a new patient, the medical assistant considers the provider's availability and how long the visit will:","take",["rain","change","sell"],"Visit length determines slot size.")
H('489.d.4.A',4,"A patient who needs a procedure that takes 60 minutes should be scheduled in a(n):","extended appointment slot",["standard 10-minute slot","lunch break","walk-in queue only"],"Match slot to need.")
H('489.d.4.B',3,"Double-booking two patients at the same time can lead to long:","wait times",["vacations","lunches","holidays"],"Overbooking causes delays.")
H('489.d.4.B',4,"Leaving a gap in the schedule for unexpected urgent visits is called building in a(n):","buffer",["parade","salary","menu"],"Buffers absorb surprises.")
H('489.d.4.C',3,"The code that describes the patient's condition on an insurance claim is the:","diagnosis code",["zip code","area code","dress code"],"Diagnosis codes report why care was needed.")
H('489.d.4.C',4,"The amount a clinic charges for a service before insurance adjustments is called the:","billed charge",["copay","deductible","premium"],"Billed charge is the listed fee.")
H('489.d.4.D',3,"Completing patient registration includes recording the patient's demographics, insurance, and:","emergency contact",["favorite color","shoe size","hobbies"],"Registration collects key data.")
H('489.d.4.D',4,"A new patient is asked to sign a consent form and a privacy notice during:","registration",["discharge","lab testing","imaging"],"Forms are signed at registration.")
H('489.d.4.E',3,"The federal insurance program for people age 65 and older is:","Medicare",["Medicaid","TRICARE","CHIP"],"Medicare covers older adults.")
H('489.d.4.E',4,"Insurance for people with low income that is run jointly by states and the federal government is:","Medicaid",["Medicare","TRICARE","COBRA"],"Medicaid is income-based.")
H('489.d.4.F',3,"An insurance card shows the plan name, group number, and the member:","ID number",["favorite doctor","blood type","weight"],"Cards identify coverage.")
H('489.d.4.F',4,"The fixed dollar amount shown on an insurance card that a patient pays for an office visit is the:","copay",["premium","deductible","coinsurance"],"The copay is a flat fee.")
H('489.d.4.G',3,"Approval required from an insurer before certain procedures are covered is called prior:","authorization",["registration","examination","vaccination"],"Prior authorization is pre-approval.")
H('489.d.4.G',4,"A list of drugs that a health plan covers is its:","formulary",["directory","itinerary","glossary"],"Formularies list covered medications.")
H('489.d.4.H',3,"A digital version of a patient's chart used by providers is an electronic:","health record",["bank account","phone book","photo album"],"EHRs store charts.")
H('489.d.4.H',4,"Components of an EHR include patient demographics, problem lists, medication lists, and:","lab results",["menus","timecards","parking logs"],"EHRs hold clinical data.")
H('489.d.4.I',3,"A benefit of an EHR is that records can be accessed quickly by authorized staff, while a risk is the possibility of a:","data breach",["paper jam","longer lunch","new carpet"],"EHRs raise security risks.")
H('489.d.4.I',4,"A system that lets patients view their own test results online is a benefit of an EHR called a patient:","portal",["tray","drawer","bulletin board"],"Portals improve access.")
H('489.d.5.A',3,"A medical assistant charts that a rash is on the front surface of the torso. The directional term for the front side is:","anterior",["posterior","superior","distal"],"Anterior = front.")
H('489.d.5.A',4,"Cutting the body from head to toe into a right half and a left half follows which anatomical plane?","sagittal plane",["coronal plane","transverse plane","oblique plane"],"Sagittal divides left and right.")
H('489.d.5.B',3,"The medical term for the study of the heart is:","cardiology",["neurology","nephrology","dermatology"],"Cardio = heart.")
H('489.d.5.B',4,"The term 'tachycardia' means a heart rate that is:","too fast",["too slow","irregular only","absent"],"Tachy = fast.")
H('489.d.5.C',3,"In the word 'nephritis,' the root 'nephr' refers to the:","kidney",["liver","lung","stomach"],"Nephr = kidney.")
H('489.d.5.C',4,"In 'arthroscopy,' the suffix '-scopy' means:","visual examination",["removal","repair","inflammation"],"-scopy = looking.")
H('489.d.6.A',3,"At the start of a visit, the medical assistant asks the patient the main reason for the visit, which is called the chief:","complaint",["billing","insurer","order"],"CC states the reason.")
H('489.d.6.A',4,"During an intake interview, the medical assistant documents current medications, allergies, and the patient's:","medical history",["favorite music","car","hobbies"],"History informs care.")
H('489.d.6.B',3,"A medical chart helps identify patient care needs by showing the patient's history, previous visits, and:","treatment plan",["parking pass","hairstyle","phone plan"],"The chart is the record of care.")
H('489.d.6.B',4,"The part of a chart that lists the provider's orders is the:","physician's orders",["billing statement","visitor log","menu"],"Orders direct care.")
H('489.d.6.C',3,"A normal resting adult heart rate is typically between 60 and:","100 beats per minute",["20 beats per minute","200 beats per minute","300 beats per minute"],"60 to 100 bpm.")
H('489.d.6.C',4,"A normal adult respiratory rate at rest is about:","12 to 20 breaths per minute",["40 to 60 breaths per minute","2 to 4 breaths per minute","80 breaths per minute"],"12 to 20 breaths/min.")
H('489.d.6.D',3,"When taking a manual blood pressure, the first sound heard through the stethoscope is the:","systolic pressure",["diastolic pressure","pulse pressure","mean pressure"],"First Korotkoff sound = systolic.")
H('489.d.6.D',4,"The blood pressure cuff should be placed on the arm so that its lower edge is about an inch above the:","antecubital space",["wrist","shoulder","elbow tip"],"Cuff placement affects accuracy.")
H('489.d.6.E',3,"A baby's head circumference, length, and weight are examples of:","anthropometric measurements",["lab tests","vital signs only","billing codes"],"Anthropometric means body measurements.")
H('489.d.6.E',4,"To measure an adult's height accurately, the patient should stand straight with the heels together and:","shoes off",["shoes on","sitting down","leaning forward"],"Remove shoes.")
H('489.d.6.F',3,"A patient weighs 176 pounds. In kilograms (1 kg = 2.2 lb) this is:","80 kg",["40 kg","387 kg","176 kg"],"176 / 2.2 = 80.")
H('489.d.6.F',4,"A patient is 5 feet 10 inches tall. In inches this is:","70 inches",["60 inches","58 inches","510 inches"],"5 x 12 + 10 = 70.")
H('489.d.7.A',3,"Testing performed at or near the site of patient care, with results available quickly, is called point of:","care testing",["sale","view","entry"],"POCT is bedside testing.")
H('489.d.7.A',4,"An advantage of point of care testing is that the provider receives results during the:","same visit",["next month","next year","week after discharge"],"Quick results.")
H('489.d.7.B',3,"A urine specimen collected after cleaning the genital area and discarding the first portion is a clean-catch:","midstream sample",["fasting sample","random sample","timed sample"],"Midstream reduces contamination.")
H('489.d.7.B',4,"A throat swab for strep is collected from the back of the throat and the:","tonsils",["tongue tip","lips","cheeks"],"Swab the tonsillar area.")
H('489.d.7.C',3,"A test performed in a medical office to measure the glucose level using a drop of blood is a point of care:","glucose test",["EKG","X-ray","MRI"],"Fingerstick glucose.")
H('489.d.7.C',4,"A rapid test that can be done in the office to check for influenza uses a:","nasal swab",["bone scan","biopsy","blood transfusion"],"Rapid flu tests use swabs.")
H('489.d.7.D',3,"A Snellen eye chart is used to screen a patient's:","visual acuity",["hearing","balance","blood pressure"],"The chart tests distance vision.")
H('489.d.7.D',4,"For a Snellen test, a patient normally stands at a distance of:","20 feet",["2 feet","50 feet","100 feet"],"20 feet is standard.")
H('489.d.7.E',3,"A 12-lead EKG records the heart's:","electrical activity",["blood sugar","oxygen level","temperature"],"EKG measures electrical signals.")
H('489.d.7.E',4,"Lead V1 on a 12-lead EKG is placed in the fourth intercostal space to the right of the:","sternum",["spine","armpit","navel"],"V1 lies right of the sternum.")
H('489.d.8.A',3,"The six rights of medication administration include right patient, right drug, right dose, right route, right time, and right:","documentation",["flavor","price","brand"],"Document after giving.")
H('489.d.8.A',4,"Before giving any medication, a medical assistant checks the label against the order three times, which helps confirm the right:","drug",["lunch","pen","color of the room"],"Label checks prevent errors.")
H('489.d.8.B',3,"A drug that lowers fever and relieves mild pain is classified as an:","analgesic and antipyretic",["anticoagulant","antibiotic only","diuretic only"],"Acetaminophen is both.")
H('489.d.8.B',4,"Amoxicillin is classified as an antibiotic and its indication is the treatment of:","bacterial infections",["viral infections","high blood pressure","diabetes"],"Antibiotics treat bacteria.")
H('489.d.8.C',3,"An unintended and harmful response to a medicine is an adverse:","event",["dose","order","label"],"Adverse events must be reported.")
H('489.d.8.C',4,"The desired beneficial effect of a medicine on the patient is called its therapeutic:","response",["failure","wall","brand"],"Therapeutic effect is the intended one.")
H('489.d.8.D',3,"A provider orders 250 mg and the vial contains 125 mg per mL. The amount to give is:","2 mL",["0.5 mL","4 mL","1 mL"],"250 / 125 = 2.")
H('489.d.8.D',4,"An order is 0.5 g and the tablets are 250 mg each. The number of tablets needed is:","2 tablets",["1 tablet","4 tablets","0.5 tablet"],"0.5 g = 500 mg; 500 / 250 = 2.")
H('489.d.8.E',3,"Before giving a medication, the medical assistant asks the patient about known:","allergies",["birthdays","hobbies","vacations"],"Allergy checks prevent reactions.")
H('489.d.8.E',4,"A drug that should not be given because it could harm a patient with a certain condition has a(n):","contraindication",["indication","dosage","brand"],"Contraindications mean avoid.")
H('489.d.8.F',3,"A medication that is placed between the cheek and the gum is given by the:","buccal route",["rectal route","topical route","intravenous route"],"Buccal = cheek.")
H('489.d.8.F',4,"A drug given under the tongue is given by the sublingual route, while a drug injected into a muscle is given by the:","intramuscular route",["oral route","topical route","inhalation route"],"IM = into muscle.")
H('489.d.8.G',3,"Before drawing up a medication from a vial, the medical assistant should clean the rubber stopper with:","an alcohol wipe",["a dry tissue","soap","a paper towel"],"Disinfect stoppers.")
H('489.d.8.G',4,"To draw up medication from an ampule, the medical assistant uses a filter needle to avoid drawing up:","glass particles",["air bubbles only","water","labels"],"Filter needles catch glass.")
H('489.d.8.H',3,"A subcutaneous injection is given into the tissue just below the:","skin",["bone","muscle","vein"],"Subcutaneous means under the skin.")
H('489.d.8.H',4,"An injection given at a 90-degree angle is typically an:","intramuscular injection",["intradermal injection","subcutaneous injection at 15 degrees","oral dose"],"IM injections go in at 90 degrees.")
H('489.d.8.I',3,"A common site for an intramuscular injection in the upper arm is the:","deltoid",["trapezius","biceps tendon","forearm"],"Deltoid is used for small volumes.")
H('489.d.8.I',4,"The ventrogluteal and vastus lateralis are also sites for:","intramuscular injections",["blood pressure checks","EKG leads","vision screening"],"These are large muscles.")
H('489.d.8.J',3,"The amount of medication to be injected, the patient's age, and muscle mass all help determine the injection:","site",["color","brand","price"],"Site selection depends on volume and patient.")
H('489.d.8.J',4,"Small muscles such as the deltoid should hold no more than about 1 mL, so larger volumes are given in a:","larger muscle",["smaller vein","bone","tendon"],"Volume limits site.")
H('489.d.8.K',3,"In needle sizes, a higher gauge number means a needle that is:","thinner",["thicker","longer","shorter"],"Higher gauge = smaller diameter.")
H('489.d.8.K',4,"A thick, viscous medication would be drawn up with a needle that has a(n):","lower gauge number",["higher gauge number","shorter handle","colored cap only"],"Thicker fluids need wider needles.")
H('489.d.8.L',3,"A 1 mL syringe used for small doses has markings in tenths and:","hundredths of a milliliter",["gallons","pounds","inches"],"Tuberculin syringes are finely marked.")
H('489.d.8.L',4,"An insulin syringe is marked in:","units",["milliliters only","ounces","grains"],"Insulin is measured in units.")
H('489.d.9.A',3,"A blood specimen that needs to be kept cold should be stored in:","a refrigerator or cooler",["a hot car","sunlight","a drawer by the heater"],"Storage affects accuracy.")
H('489.d.9.A',4,"A specimen being sent to an outside lab is placed in a sealed biohazard bag to prevent:","leaks and exposure",["noise","fading","rust"],"Transport safety.")
H('489.d.9.B',3,"In the order of draw, the first tube collected is usually the blood culture bottle or the:","light blue top",["lavender top","gray top","green top"],"Light blue (citrate) comes early.")
H('489.d.9.B',4,"Following the order of draw is important because additives from one tube can contaminate the next and change:","test results",["tube color only","needle length","label size"],"Carryover alters results.")
H('489.d.9.C',3,"A tube with EDTA used for a complete blood count has a:","lavender top",["gray top","red top","green top"],"Lavender = EDTA.")
H('489.d.9.C',4,"A gray-top tube, which contains sodium fluoride, is commonly used for testing:","blood glucose",["clotting time","electrolytes","cultures"],"Gray tops preserve glucose.")
H('489.d.9.D',3,"The vein most often used for a routine blood draw is in the:","antecubital area",["ankle","neck","palm"],"Median cubital vein is common.")
H('489.d.9.D',4,"The vein located in the middle of the antecubital area and most often chosen for venipuncture is the median:","cubital vein",["femoral vein","jugular vein","aorta"],"It is large and stable.")
H('489.d.9.E',3,"Before inserting the needle, the tourniquet is placed above the site and should be left on for no longer than:","one minute",["ten minutes","an hour","five minutes"],"Prolonged tourniquet use alters results.")
H('489.d.9.E',4,"After the needle is removed, pressure is applied to the puncture site with gauze to stop:","bleeding",["itching","movement","speaking"],"Post-procedure care.")
H('489.d.9.F',3,"Tube labels should include the patient's full name, date of birth, date and time, and the collector's:","initials",["favorite food","phone","address of the clinic"],"Labels identify the sample.")
H('489.d.9.F',4,"A specimen should be labeled in the presence of the:","patient",["pharmacist","receptionist","visitor"],"Label at bedside to avoid mix-ups.")
H('489.d.10.A',3,"According to Erikson, the stage of life when a person focuses on identity and independence is:","adolescence",["infancy","old age","toddlerhood"],"Adolescence centers on identity.")
H('489.d.10.A',4,"Toddlers developing independence is the stage that psychologists call autonomy versus:","shame and doubt",["trust and mistrust","identity confusion","integrity and despair"],"Erikson's second stage.")
H('489.d.10.B',3,"A patient who denies a diagnosis even after being told it is using the defense mechanism of:","denial",["acceptance","humor","bargaining"],"Denial is protective.")
H('489.d.10.B',4,"A patient who lashes out at staff because of fear about a diagnosis may be using a coping mechanism called:","displacement",["acceptance","humor","sublimation only"],"Displacement redirects emotion.")
H('489.d.10.C',3,"A legal document that states a person's wishes about medical treatment if they cannot speak for themselves is an advance:","directive",["receipt","invoice","schedule"],"Advance directives guide care.")
H('489.d.10.C',4,"A person chosen to make health care decisions for a patient who cannot is a health care:","proxy",["clerk","vendor","driver"],"Proxy acts for the patient.")
H('489.d.10.D',3,"When working with a patient who has a mental health condition, the medical assistant should respond in a calm and:","nonjudgmental manner",["rushed manner","sarcastic manner","loud manner"],"Respectful care.")
H('489.d.10.D',4,"If a patient says they are thinking of harming themselves, the medical assistant should:","tell the provider immediately",["wait until the end of the day","ignore it","joke about it"],"Safety concerns are urgent.")
H('489.d.10.E',3,"A patient who lacks reliable transportation may miss appointments, which is an example of how socioeconomic factors affect:","access to care",["height","eye color","hair color"],"Barriers affect health.")
H('489.d.10.E',4,"Lack of health insurance and low income are socioeconomic factors that can lead patients to delay:","preventive care",["breathing","sleeping","blinking"],"Costs delay care.")
H('489.d.10.F',3,"A patient from a culture that values family involvement may want relatives present for decisions, so the medical assistant should show:","cultural sensitivity",["impatience","assumptions","stereotypes"],"Respect values.")
H('489.d.10.F',4,"When an interpreter is needed, the medical assistant should use a trained interpreter rather than a:","family child",["certified professional","phone interpreter service","staff interpreter"],"Avoid using minors as interpreters.")
H('489.d.11.A',3,"Treating all blood and body fluids as if they could be infectious is the basis of standard:","precautions",["scheduling","billing","coding"],"Standard precautions protect all.")
H('489.d.11.A',4,"The single most important action for preventing the spread of infection is:","hand hygiene",["wearing jewelry","opening windows","using perfume"],"Hand hygiene prevents spread.")
H('489.d.11.B',3,"Malaria spread by the bite of an infected mosquito is an example of transmission by a:","vector",["fomite","droplet","airborne cloud"],"Vectors carry pathogens.")
H('489.d.11.B',4,"A doorknob that carries germs from one person to another is a(n):","fomite",["vector","reservoir host","carrier species"],"Fomites are contaminated objects.")
H('489.d.11.C',3,"A sign on a patient's door that shows the room requires airborne precautions warns staff to wear a:","N95 respirator",["bandana","paper hat","scarf"],"N95 for airborne.")
H('489.d.11.C',4,"Contact precautions signage tells staff to wear a gown and:","gloves",["earplugs","a hat only","sandals"],"Gown and gloves for contact.")
H('489.d.11.D',3,"Gloves, masks, gowns, and face shields are all examples of:","personal protective equipment",["office supplies","medications","billing tools"],"PPE.")
H('489.d.11.D',4,"The purpose of eye protection such as goggles is to guard against:","splashes of body fluids",["bright lights","loud noise","cold"],"Eye protection prevents exposure.")
H('489.d.11.E',3,"During a blood draw, the medical assistant wears gloves and a:","lab coat",["swimsuit","raincoat","apron for cooking"],"Venipuncture requires gloves.")
H('489.d.11.E',4,"When a patient may cough or sneeze during a procedure, the medical assistant should add a:","face mask",["watch","ring","scarf"],"Droplet protection.")
H('489.d.11.F',3,"When putting on PPE, the correct first step is to perform:","hand hygiene",["glove removal","gown removal","mask removal"],"Start clean.")
H('489.d.11.F',4,"When doffing PPE, the item that is usually removed first is the:","gloves",["mask","goggles","hair cover"],"Gloves are most contaminated.")
H('489.d.11.G',3,"A rigid, puncture-resistant container for used needles is a:","sharps container",["trash bag","shredding bin","paper box"],"Sharps need special disposal.")
H('489.d.11.G',4,"Paper that contains patient information is disposed of in a:","shredding bin",["recycling bin","sink","hallway"],"Shredding protects privacy.")
H('489.d.11.H',3,"After giving an injection, a used needle should be placed in a sharps container without:","recapping",["counting","labeling","weighing"],"Never recap.")
H('489.d.11.H',4,"A sharps container should be replaced when it is about:","three-fourths full",["empty","one-fourth full","painted"],"Do not overfill.")
H('489.d.11.I',3,"A severe, life-threatening allergic reaction with swelling of the throat and trouble breathing is:","anaphylaxis",["asthma only","syncope","fever"],"Anaphylaxis is an emergency.")
H('489.d.11.I',4,"The first-line medication for anaphylaxis, often given with an auto-injector, is:","epinephrine",["acetaminophen","insulin","penicillin"],"Epinephrine reverses the reaction.")
H('489.d.11.J',3,"Vaccines and some medications must be stored in a refrigerator at 36 to 46 degrees:","Fahrenheit",["Celsius only","Kelvin","Rankine"],"2 to 8 C is 36 to 46 F.")
H('489.d.11.J',4,"A refrigerator used for vaccines should have its temperature recorded:","every day",["once a year","never","once a decade"],"Daily logs prevent spoilage.")
H('489.d.11.K',3,"A document that tells staff about the hazards of a chemical and first aid measures is a safety data sheet, abbreviated:","SDS",["EHR","DEA","CPT"],"SDS describes chemicals.")
H('489.d.11.K',4,"If bleach is splashed in the eye, the medical assistant should check the SDS and flush the eye with:","water",["alcohol","oil","gel"],"First aid for eye exposure.")
H('489.d.11.L',3,"Practices that reduce the number of germs but do not remove all microbes are called medical:","asepsis",["sterility","surgery","pathology"],"Medical asepsis is clean technique.")
H('489.d.11.L',4,"Washing hands and disinfecting an exam table between patients is an example of medical asepsis, which differs from surgical asepsis because it does not make the area completely:","sterile",["clean","dry","visible"],"Surgical asepsis is sterile.")

# ---- 490 Respiratory Therapy I ----
H('490.d.1.A',3,"A student reads a manual describing how a ventilator delivers breaths. Understanding it requires interpreting complex:","technical material",["comic strips","menus","jokes"],"Technical reading skills.")
H('490.d.1.A',4,"A respiratory therapist uses a device manual to find the settings for a nebulizer. The best way to interpret unfamiliar terms is to look them up in a:","medical glossary",["novel","comic","menu"],"Glossaries clarify terms.")
H('490.d.1.B',3,"A patient's religious belief may influence whether they accept certain treatments, so the therapist should show:","respect for beliefs",["judgment","impatience","dismissal"],"Cultural competence.")
H('490.d.1.B',4,"A therapist caring for patients with different cultural backgrounds should ask each patient about their care:","preferences",["birthdays","shoes","cars"],"Ask about preferences.")
H('490.d.1.C',3,"A patient receives 40 percent oxygen. The percent of oxygen in room air is about:","21 percent",["50 percent","10 percent","78 percent"],"Room air is 21% O2.")
H('490.d.1.C',4,"A patient breathes 16 times per minute with a tidal volume of 500 mL. The minute ventilation is:","8000 mL",["800 mL","516 mL","32000 mL"],"16 x 500 = 8000 mL.")
H('490.d.1.D',3,"The body's ability to keep its internal conditions stable is:","homeostasis",["hibernation","digestion","metamorphosis"],"Homeostasis maintains balance.")
H('490.d.1.D',4,"The lungs help regulate blood pH by removing carbon dioxide, which is part of the body's acid-base:","balance",["color","taste","weight"],"CO2 affects pH.")
H('490.d.2.A',3,"The iron lung, used during polio epidemics, was an early form of:","mechanical ventilation",["dialysis","anesthesia","imaging"],"Iron lungs were early ventilators.")
H('490.d.2.A',4,"Modern ventilators have advanced from large negative-pressure tanks to computer-controlled machines that deliver:","positive pressure breaths",["suction only","cold air","sound waves"],"Positive pressure is current practice.")
H('490.d.2.B',3,"A respiratory therapist who works in a hospital's intensive care unit might manage patients on a:","ventilator",["treadmill","bicycle","bed lift only"],"RTs manage ventilators.")
H('490.d.2.B',4,"Respiratory therapists may also work in home care, teaching patients to use oxygen equipment and:","nebulizers",["televisions","ovens","phones"],"Home care RTs educate.")
H('490.d.2.C',3,"Becoming a respiratory therapist typically requires at least an associate degree from an accredited:","respiratory therapy program",["culinary program","law school only","art program"],"Accredited program needed.")
H('490.d.2.C',4,"After graduating, a therapist earns the CRT credential by passing an exam given by the National Board for Respiratory:","Care",["Cooking","Cleaning","Cars"],"NBRC offers credentials.")
H('490.d.3.A',3,"The agency that sets and enforces workplace safety standards in hospitals is OSHA, which stands for the Occupational Safety and Health:","Administration",["Alliance","Association","Agreement"],"OSHA enforces standards.")
H('490.d.3.A',4,"The Joint Commission accredits hospitals and sets standards for patient:","safety",["parking","uniforms","menus"],"Accreditation standards.")
H('490.d.3.B',3,"Safety steps used for patients known to have a germ that spreads by respiratory droplets are called transmission-based:","precautions",["recipes","schedules","reports"],"Transmission-based precautions.")
H('490.d.3.B',4,"A patient with tuberculosis is placed in a negative-pressure room with airborne:","precautions",["decorations","visitors","menus"],"TB needs airborne precautions.")
H('490.d.3.C',3,"Using the legs instead of the back when lifting a heavy oxygen cylinder is proper body:","mechanics",["music","painting","art"],"Good body mechanics.")
H('490.d.3.C',4,"Oxygen cylinders should be secured upright with a chain or stand to prevent them from:","falling",["cooling","rusting at night","changing color"],"Cylinders are heavy and hazardous.")
H('490.d.4.A',3,"The heart chamber that pumps oxygen-rich blood to the body is the left:","ventricle",["atrium","valve","vein"],"Left ventricle pumps to the aorta.")
H('490.d.4.A',4,"The valve between the left atrium and the left ventricle is the:","mitral valve",["tricuspid valve","aortic valve","pulmonary valve"],"Mitral valve.")
H('490.d.4.B',3,"The windpipe that carries air from the larynx to the bronchi is the:","trachea",["esophagus","alveolus","pharynx"],"Trachea.")
H('490.d.4.B',4,"Gas exchange between air and blood takes place in tiny air sacs called:","alveoli",["bronchi","villi","nephrons"],"Alveoli exchange gases.")
H('490.d.4.C',3,"Blood from the body returns to the right atrium through the:","vena cava",["aorta","pulmonary vein","carotid artery"],"Vena cava returns blood.")
H('490.d.4.C',4,"After leaving the right ventricle, blood travels through the pulmonary artery to the:","lungs",["brain","kidneys","liver"],"Pulmonary circulation.")
H('490.d.4.D',3,"A chronic lung disease that includes emphysema and chronic bronchitis is:","COPD",["ADHD","AIDS","ALS"],"COPD obstructs airflow.")
H('490.d.4.D',4,"A heart condition in which the heart cannot pump enough blood to meet the body's needs is:","heart failure",["tonsillitis","appendicitis","bronchitis"],"Heart failure reduces output.")
H('490.d.5.A',3,"A breathing exercise in which a patient inhales through the nose and exhales slowly through pursed lips is called:","pursed-lip breathing",["gasping","hyperventilation","breath holding"],"Pursed-lip slows breathing.")
H('490.d.5.A',4,"Deep breathing exercises using a device that shows how deeply a patient inhales are done with an incentive:","spirometer",["thermometer","stethoscope","otoscope"],"Spirometry encourages deep breaths.")
H('490.d.5.B',3,"Techniques such as chest physiotherapy and coughing exercises that help clear secretions are called airway clearance:","therapies",["menus","recipes","tests"],"Airway clearance.")
H('490.d.5.B',4,"Hyperinflation therapy uses deep breaths to help prevent collapse of the lungs, which is called:","atelectasis",["asthma","pneumothorax","bronchitis"],"Atelectasis is collapse.")
H('490.d.5.C',3,"A tube placed through the mouth into the windpipe to help a patient breathe is an:","endotracheal tube",["feeding tube","chest tube","IV tube"],"ET tube.")
H('490.d.5.C',4,"A surgical opening in the neck into the trachea for long-term breathing support is a:","tracheostomy",["gastrostomy","colostomy","thoracotomy"],"Tracheostomy.")
H('490.d.5.D',3,"The tip of an endotracheal tube should sit above the carina, which is where the trachea divides into the:","main bronchi",["lung lobes","pulmonary veins","alveoli"],"Proper ET position.")
H('490.d.5.D',4,"The best way to confirm endotracheal tube position after placement is to check a chest:","X-ray",["scale","thermometer","hearing test"],"X-ray confirms position.")
H('490.d.5.E',3,"A small device clipped to a fingertip that measures the percent of oxygen in the blood is a pulse:","oximeter",["thermometer","glucometer","sphygmomanometer"],"Pulse oximeter.")
H('490.d.5.E',4,"A blood sample taken from an artery to measure oxygen, carbon dioxide, and pH is an arterial blood:","gas",["culture","count","type"],"ABG.")
H('490.d.5.F',3,"A low-flow device that delivers oxygen through two small prongs in the nostrils is a nasal:","cannula",["mask","tent","hood"],"Nasal cannula.")
H('490.d.5.F',4,"A device with a reservoir bag that covers the nose and mouth and delivers a high concentration of oxygen is a non-rebreather:","mask",["cannula","tent","helmet only"],"Non-rebreather.")
H('490.d.5.G',3,"A machine that takes oxygen from room air and concentrates it for home use is an oxygen:","concentrator",["cylinder","humidifier","regulator"],"Concentrator.")
H('490.d.5.G',4,"Oxygen is a fire hazard, so patients using it must not be near open flames or:","smoking",["television","music","books"],"No smoking.")
H('490.d.6.A',3,"A medication that relaxes airway muscles and opens the airways is a:","bronchodilator",["antibiotic","diuretic","anticoagulant"],"Bronchodilators open airways.")
H('490.d.6.A',4,"Albuterol is a short-acting bronchodilator commonly used as a:","rescue inhaler",["daily vitamin","antibiotic","sleep aid"],"Albuterol relieves symptoms.")
H('490.d.6.B',3,"A common side effect of albuterol is a fast heart rate, also known as:","tachycardia",["bradycardia","hypotension","hypothermia"],"Beta agonists raise heart rate.")
H('490.d.6.B',4,"Inhaled corticosteroids can cause a fungal infection of the mouth called:","thrush",["measles","mumps","strep"],"Rinse after use.")
H('490.d.6.C',3,"A device that turns liquid medicine into a fine mist for inhalation is a:","nebulizer",["syringe","tourniquet","scalpel"],"Nebulizer.")
H('490.d.6.C',4,"A metered-dose inhaler delivers each dose from a pressurized canister, and a spacer is used to improve:","drug delivery to the lungs",["flavor","cost","color"],"Spacers help delivery.")
H('490.d.6.D',3,"Beta agonists can increase a patient's heart rate and:","blood pressure",["height","weight loss","hair growth"],"Vital signs change.")
H('490.d.6.D',4,"After giving a bronchodilator, a respiratory therapist rechecks the patient's heart rate and:","breath sounds",["shoe size","insurance","height"],"Assess response.")
H('490.d.7.A',3,"The vital sign that shows how fast the heart beats is the:","pulse",["temperature","height","weight"],"Pulse = heart rate.")
H('490.d.7.A',4,"A respiratory therapist counts respirations for a full minute without letting the patient know, to avoid changing the:","breathing pattern",["blood type","height","weight"],"Patients alter breathing when watched.")
H('490.d.7.B',3,"A position with the head of the bed raised 45 to 90 degrees to ease breathing is the:","Fowler's position",["prone position","supine position","Trendelenburg position"],"Fowler's helps breathing.")
H('490.d.7.B',4,"A patient lying flat on the back is in the supine position, while a patient lying on the stomach is in the:","prone position",["Fowler's position","lateral position","sitting position"],"Prone = face down.")
H('490.d.7.C',3,"During a cardiac arrest, the respiratory therapist's role may include providing:","ventilation",["billing","scheduling","filing"],"RTs manage airway.")
H('490.d.7.C',4,"In a high-stress situation such as a code, the respiratory therapist keeps calm and uses clear, closed-loop:","communication",["silence","music","jokes"],"Closed-loop communication.")
H('490.d.7.D',3,"For adult CPR, chest compressions are done at a rate of 100 to 120 per minute at a depth of at least:","2 inches",["half an inch","5 inches","1 inch"],"At least 2 inches.")
H('490.d.7.D',4,"An automated external defibrillator is used to analyze the heart rhythm and deliver a shock when needed. It is abbreviated:","AED",["EKG","MRI","CPR"],"AED.")
H('490.d.7.E',3,"Speaking in a calm tone and giving simple explanations to an anxious patient is therapeutic:","communication",["avoidance","argument","delay"],"Therapeutic communication.")
H('490.d.7.E',4,"A therapist who says, 'Tell me more about how you're feeling' is using an:","open-ended question",["closed question","yes/no question","command"],"Open-ended invites detail.")
H('490.d.8.A',3,"The ethical principle that a patient has the right to make their own choices about care is:","autonomy",["justice","beneficence","fidelity"],"Autonomy.")
H('490.d.8.A',4,"A patient's right to refuse a treatment is protected by the Patient's:","Bill of Rights",["Menu","Calendar","Newsletter"],"Rights include refusal.")
H('490.d.8.B',3,"Falsifying a patient's record is unacceptable behavior that can lead to loss of a professional:","license",["lunch","uniform","parking"],"Falsification has penalties.")
H('490.d.8.B',4,"Sharing a patient's information on social media violates:","HIPAA",["OSHA","ADA","FDA"],"Privacy law.")
H('490.d.8.C',3,"The professional organization for respiratory therapists in the United States is the American Association for Respiratory:","Care",["Cooking","Cars","Classes"],"AARC.")
H('490.d.8.C',4,"A state board that licenses respiratory therapists to practice is a regulatory:","agency",["club","team","band"],"State licensure.")
H('490.d.8.D',3,"A patient with a terminal illness refuses a ventilator. The therapist faces an ethical dilemma between respecting autonomy and the duty to:","preserve life",["save time","reduce cost","finish work"],"Ethical dilemma.")
H('490.d.8.D',4,"A do-not-resuscitate order means that CPR should not be performed if the patient's:","heart stops",["name changes","bill is high","room is cold"],"DNR.")

# ---- 491 Respiratory Therapy II ----
H('491.d.1.A',3,"A therapist reviews a research article on high-flow oxygen therapy. Evaluating how well the study was designed is part of analyzing complex technical:","material",["recipes","songs","menus"],"Technical analysis.")
H('491.d.1.A',4,"When two journal articles give different results for a ventilator strategy, the therapist should compare the study methods and sample:","sizes",["fonts","colors","titles"],"Compare methods.")
H('491.d.1.B',3,"A therapist who learns that a patient's language is not English should arrange for a qualified:","interpreter",["mascot","gift","map"],"Interpreters support care.")
H('491.d.1.B',4,"Religious beliefs that forbid certain blood products affect how a therapist plans the patient's:","care",["lunch","parking","uniform"],"Beliefs shape care.")
H('491.d.1.C',3,"A patient's tidal volume is 450 mL and the respiratory rate is 20. The minute ventilation is:","9000 mL",["900 mL","470 mL","4500 mL"],"450 x 20 = 9000.")
H('491.d.1.C',4,"A patient needs a FiO2 of 0.4. As a percentage, this is:","40 percent",["4 percent","0.4 percent","400 percent"],"0.4 = 40%.")
H('491.d.1.D',3,"Carbon dioxide dissolved in blood forms carbonic acid, so a rise in CO2 makes the blood more:","acidic",["basic","salty","sweet"],"CO2 lowers pH.")
H('491.d.1.D',4,"Breathing too fast blows off carbon dioxide and can cause the blood to become too:","alkaline",["acidic","thick","warm"],"Hyperventilation raises pH.")
H('491.d.2.A',3,"The American Association for Respiratory Care publishes clinical practice guidelines that help therapists apply the best:","standards of practice",["menus","movies","fashion"],"Guidelines guide care.")
H('491.d.2.A',4,"Evidence-based guidelines for ventilator weaning are updated as new research becomes available, so therapists must stay:","current",["silent","absent","unaware"],"Update practice.")
H('491.d.2.B',3,"A patient on airborne precautions should be cared for in a room with negative:","pressure",["color","price","music"],"Negative pressure room.")
H('491.d.2.B',4,"Before entering a droplet-isolation room, a therapist should wear a surgical:","mask",["scarf","earring","hat only"],"Droplet precautions.")
H('491.d.2.C',3,"When moving a patient who is on a ventilator, the therapist protects the airway and uses proper body:","mechanics",["music","budget","colors"],"Safe transfers.")
H('491.d.2.C',4,"Securing ventilator tubing so it is not pulled when the patient is turned helps prevent accidental:","extubation",["intubation","hydration","vaccination"],"Prevent tube dislodgement.")
H('491.d.3.A',3,"Automatic breathing changes in response to carbon dioxide are regulated mainly by the brainstem and the branch that works without conscious thought, the autonomic:","nervous system",["skeletal system","digestive system","integumentary system"],"ANS regulates breathing.")
H('491.d.3.A',4,"Stimulating the sympathetic nervous system causes the bronchial airways to:","widen",["narrow","close","shrink"],"Sympathetic dilates airways.")
H('491.d.3.B',3,"The organs that help control acid-base balance by excreting hydrogen ions and conserving bicarbonate are the:","kidneys",["lungs only","liver only","spleen"],"Renal compensation.")
H('491.d.3.B',4,"Renal compensation for respiratory acidosis takes hours to days and works by retaining:","bicarbonate",["carbon dioxide","oxygen","nitrogen"],"Kidneys retain HCO3.")
H('491.d.3.C',3,"Heart failure can cause fluid to back up into the lungs, showing how the cardiac and respiratory systems:","interact",["compete","ignore each other","never meet"],"Systems interact.")
H('491.d.3.C',4,"A patient with a failing heart often has trouble breathing because blood backs up in the:","pulmonary circulation",["digestive tract","skin","bones"],"Congestion causes dyspnea.")
H('491.d.3.D',3,"On an EKG, a normal heartbeat pattern that starts in the sinus node at 60 to 100 beats per minute is called normal sinus:","rhythm",["failure","tumor","breath"],"NSR.")
H('491.d.3.D',4,"A chaotic, quivering rhythm of the ventricles that causes no effective pumping is ventricular:","fibrillation",["tachycardia sinus","bradycardia","standstill only"],"V-fib requires defibrillation.")
H('491.d.3.E',3,"A mechanical ventilator delivers breaths using pressure or:","volume",["color","price","music"],"Modes: volume or pressure.")
H('491.d.3.E',4,"The therapist adjusts the ventilator's tidal volume, rate, and oxygen concentration based on the patient's:","blood gas results",["birthday","hobbies","insurance"],"ABG-guided settings.")
H('491.d.4.A',3,"Slow, deep belly breathing taught to relax and improve ventilation is called:","diaphragmatic breathing",["gasping","panting","sniffing"],"Diaphragmatic breathing.")
H('491.d.4.A',4,"The incentive spirometer encourages a patient to take a slow, deep breath and hold it for at least:","three seconds",["one second","thirty seconds","five minutes"],"Hold 3-5 seconds.")
H('491.d.4.B',3,"In a lab simulation, the therapist uses a bag-valve-mask to provide breaths to a mannequin that is:","not breathing",["running","sleeping","laughing"],"BVM ventilation.")
H('491.d.4.B',4,"The head-tilt chin-lift maneuver helps open the airway by lifting the:","tongue away from the throat",["feet","arms","stomach"],"Tongue blocks the airway.")
H('491.d.4.C',3,"Using a device that vibrates the chest wall to help loosen mucus is an airway clearance:","therapy",["menu","invoice","report"],"Chest physiotherapy.")
H('491.d.4.C',4,"Patients with cystic fibrosis often use airway clearance because of thick:","mucus",["bones","blood","hair"],"CF produces thick secretions.")
H('491.d.4.D',3,"On a chest X-ray, air-filled normal lungs appear:","dark",["white","red","green"],"Air is dark.")
H('491.d.4.D',4,"Fluid or pneumonia in the lungs appears on a chest X-ray as a:","white area",["black area","clear area","hole"],"Infiltrates are white.")
H('491.d.4.E',3,"A normal arterial blood pH range is:","7.35 to 7.45",["6.0 to 6.5","8.0 to 8.5","1.0 to 2.0"],"Normal pH is slightly alkaline.")
H('491.d.4.E',4,"An ABG with pH 7.30 and PaCO2 55 mmHg suggests:","respiratory acidosis",["respiratory alkalosis","metabolic alkalosis","normal values"],"Low pH and high CO2.")
H('491.d.4.F',3,"A nasal cannula delivers a low oxygen flow, usually between 1 and 6:","liters per minute",["inches per hour","pounds per day","cups per minute"],"NC flow range.")
H('491.d.4.F',4,"For a patient who needs a high concentration of oxygen, the therapist may select a:","non-rebreather mask",["nasal cannula at 1 L/min","room air","simple tape"],"High FiO2.")
H('491.d.4.G',3,"Listening to breath sounds with a stethoscope is called:","auscultation",["palpation","percussion","inspection"],"Auscultation uses a stethoscope.")
H('491.d.4.G',4,"A high-pitched whistling sound heard on exhalation, common in asthma, is a:","wheeze",["crackle","rub","snore"],"Wheezes mean narrowed airways.")
H('491.d.4.H',3,"A care plan for a patient with asthma includes identifying triggers and using a controller medicine and a:","rescue inhaler",["blanket","crutch","splint"],"Asthma plan.")
H('491.d.4.H',4,"For COPD, a care plan encourages smoking cessation, vaccinations, and pulmonary:","rehabilitation",["tourism","decoration","filing"],"Pulmonary rehab.")
H('491.d.4.I',3,"In a simulated emergency, the respiratory therapist's priority is to secure the patient's:","airway",["paperwork","lunch","parking"],"Airway first.")
H('491.d.4.I',4,"In advanced life support, the therapist assists the team and monitors the patient's oxygenation with:","capnography",["thermometer","scale","ruler"],"ETCO2 monitoring.")
H('491.d.4.J',3,"A therapist teaches a patient with COPD to recognize signs that the condition is getting worse, which is part of patient:","education",["billing","cooking","parking"],"Patient education.")
H('491.d.4.J',4,"Teaching a patient how to clean a nebulizer after each treatment helps prevent:","infection",["boredom","loud sounds","fading"],"Clean equipment.")
H('491.d.5.A',3,"Medications such as inhaled steroids and bronchodilators are applied in respiratory therapy to treat:","airway inflammation and narrowing",["broken bones","skin rashes","hair loss"],"Respiratory drugs treat airways.")
H('491.d.5.A',4,"A mucolytic agent is used in respiratory care to make mucus:","thinner",["thicker","darker","sweeter"],"Mucolytics thin mucus.")
H('491.d.5.B',3,"A patient with a known allergy to a medication should not receive it, since the allergy is a:","contraindication",["indication","dosage","side benefit"],"Contraindication.")
H('491.d.5.B',4,"Tremors and a fast heartbeat after albuterol are examples of a drug's:","side effects",["indications","orders","labels"],"Side effects.")
H('491.d.5.C',3,"A dry powder inhaler requires the patient to breathe in:","quickly and deeply",["slowly and shallowly","through the nose only","not at all"],"DPI needs a strong inhale.")
H('491.d.5.C',4,"A small-volume nebulizer works best when the patient breathes:","slowly and deeply",["rapidly and shallowly","not at all","only through the nose"],"Slow deep breaths.")
H('491.d.5.D',3,"Before starting a bronchodilator treatment, the therapist records the patient's heart rate, respiratory rate, and:","breath sounds",["address","insurance","shoe size"],"Baseline.")
H('491.d.5.D',4,"After a treatment, a decrease in wheezing and an improvement in peak flow suggest that the therapy was:","effective",["harmful","wrong","unnecessary"],"Response assessment.")
H('491.d.6.A',3,"A patient with capacity has the right to accept or refuse treatment, which is a part of informed:","consent",["billing","coding","scheduling"],"Informed consent.")
H('491.d.6.A',4,"The Patient's Bill of Rights states that patients have the right to considerate and respectful:","care",["billing","gossip","delays"],"Rights.")
H('491.d.6.B',3,"Leaving a patient unattended on a ventilator without a handoff could be considered professional:","negligence",["training","recognition","reward"],"Negligence.")
H('491.d.6.B',4,"A therapist who is impaired by drugs or alcohol at work could lose their professional:","license",["lunch","badge color","parking"],"Impairment is unacceptable.")
H('491.d.6.C',3,"A document that states a patient's wishes about being placed on a ventilator is an advance:","directive",["receipt","invoice","agenda"],"Advance directive.")
H('491.d.6.C',4,"A therapist may face an ethical dilemma when a family wants to continue ventilation but the patient previously stated a wish to:","stop treatment",["start treatment","leave work","move rooms"],"Dilemma: family versus patient wishes.")
H('491.d.7.A',3,"A respiratory therapist may advance professionally by earning a bachelor's degree or specialty credentials such as the Adult Critical Care:","Specialist",["Cashier","Chef","Cleaner"],"ACCS credential.")
H('491.d.7.A',4,"A therapist who wants to become a department manager might pursue a degree in healthcare:","management",["cooking","fashion","art"],"Management path.")
H('491.d.7.B',3,"To work as a respiratory therapist in Texas, a graduate must pass the national exam and obtain a state:","license",["parking pass","discount","coupon"],"Licensure.")
H('491.d.7.B',4,"To keep a license active, therapists must complete a required number of continuing education:","hours",["songs","parties","games"],"CEUs.")

# ---- 492 Healthcare Management ----
H('492.d.1.A',3,"Planning, organizing, and directing the operations of hospitals, clinics, and other health organizations is known as healthcare:","management",["tourism","sales","design"],"Healthcare management.")
H('492.d.1.A',4,"A person who oversees the daily operations of a medical practice and its staff is a practice:","administrator",["patient","vendor","visitor"],"Practice administrator.")
H('492.d.1.B',3,"A chief financial officer in a hospital is responsible for the organization's:","finances",["laundry","cooking","landscaping"],"CFO handles finance.")
H('492.d.1.B',4,"A nurse manager supervises the nursing staff on a unit and is responsible for scheduling and:","staffing",["marketing","construction","legal filings"],"Nurse managers handle unit staffing.")
H('492.d.1.C',3,"In a hospital, departments that cooperate to provide smooth patient care demonstrate good:","teamwork",["rivalry","delay","gossip"],"Teamwork improves care.")
H('492.d.1.C',4,"A positive organizational culture in healthcare tends to improve staff morale and patient:","outcomes",["complaints","delays","errors"],"Culture affects outcomes.")
H('492.d.1.D',3,"Changes in laws, technology, and the economy are all outside factors that influence healthcare management:","strategies",["recipes","games","clothes"],"External factors.")
H('492.d.1.D',4,"An aging population increases the demand for services such as long-term care and:","home health",["video games","fashion retail","toy sales"],"Demographics shape demand.")
H('492.d.1.E',3,"A manager who finds that a coworker is falsifying records should report it, which is an example of ethical workplace:","behavior",["failure","delay","denial"],"Ethical behavior.")
H('492.d.1.E',4,"When making an ethical decision, a manager considers the effect on patients, staff, and the:","organization",["weather","menu","calendar"],"Stakeholder impact.")
H('492.d.1.F',3,"A hospital offering free health screenings for the community is an example of a socially responsible management:","policy",["trick","penalty","delay"],"Community benefit.")
H('492.d.1.F',4,"Programs that provide care to people who cannot pay are examples of policies that improve:","access to care",["profits only","parking","signage"],"Charity care.")
H('492.d.2.A',3,"A facility that provides inpatient care for serious illness and emergencies is a:","hospital",["pharmacy","gym","bank"],"Hospitals provide acute care.")
H('492.d.2.A',4,"A system in which a patient's primary care provider coordinates all care and referrals is called a(n):","gatekeeper model",["free-for-all","walk-in model","open market"],"HMOs use gatekeepers.")
H('492.d.2.B',3,"An ongoing process that uses data to improve patient care and reduce errors is quality:","improvement",["decoration","reduction","loss"],"QI.")
H('492.d.2.B',4,"A hospital tracks the number of patients who return within 30 days as one measure of care:","quality",["color","price","distance"],"Readmission rates.")
H('492.d.2.C',3,"Software that stores patient records electronically is an example of health information:","technology",["decor","fashion","furniture"],"HIT.")
H('492.d.2.C',4,"One barrier to adopting new health information technology in a small clinic is the high initial:","cost",["color","noise","weather"],"Cost.")
H('492.d.2.D',3,"A payment model in which providers are paid for each procedure or visit they perform is called fee-for-:","service",["time","fun","name"],"Fee-for-service.")
H('492.d.2.D',4,"A fixed amount paid per patient per month to a provider regardless of how many visits occur is:","capitation",["fee-for-service","coinsurance","deductible"],"Capitation.")
H('492.d.2.E',3,"Money a hospital earns from patient care is revenue, while money spent on salaries and supplies is an:","expense",["income","asset","profit"],"Revenue vs expense.")
H('492.d.2.E',4,"A hospital's income from gifts and grants, not patient care, is classified as:","non-operating revenue",["operating expense","salary","depreciation"],"Donations.")
H('492.d.2.F',3,"Revenue-cycle management tracks a patient's account from registration to final:","payment",["discharge party","supply order","visit schedule only"],"RCM.")
H('492.d.2.F',4,"Denied insurance claims are reviewed and resubmitted as part of the revenue:","cycle",["parade","mile","rate"],"Revenue cycle.")
H('492.d.2.G',3,"A friendly front desk, short wait times, and a clean waiting room are part of good customer:","service",["spending","denial","trouble"],"Customer service.")
H('492.d.2.G',4,"A hospital advertising its new cancer center in the community is using:","marketing",["accounting","billing","coding"],"Marketing promotes services.")
H('492.d.3.A',3,"Groups such as the American College of Healthcare Executives set professional:","standards",["menus","recipes","games"],"Associations set standards.")
H('492.d.3.A',4,"A state agency that licenses hospitals and inspects them for compliance is a(n):","regulatory agency",["sports league","fan club","music group"],"Regulators inspect.")
H('492.d.3.B',3,"The law that protects the privacy of patient information is:","HIPAA",["OSHA","ADA","FDA"],"HIPAA.")
H('492.d.3.B',4,"The Patient's Bill of Rights says patients have the right to know their treatment options and to give informed:","consent",["feedback","gifts","complaints only"],"Informed consent.")
H('492.d.3.C',3,"A manager who ignores repeated safety violations may be held legally responsible and face:","fines or lawsuits",["rewards","praise","promotions"],"Consequences.")
H('492.d.3.C',4,"Hiding a medical error from a patient is unethical and can lead to a loss of:","trust",["luggage","paper","weight"],"Honesty.")
H('492.d.3.D',3,"A hospital purchasing manager awards a contract to a company owned by a family member. This is a(n):","conflict of interest",["fair practice","budget plan","safety check"],"COI.")
H('492.d.3.D',4,"A conflict of interest should be disclosed to the organization so that decisions remain:","unbiased",["secret","hidden","rushed"],"Disclosure.")
H('492.d.3.E',3,"Billing for services never provided is fraud, while unnecessary use of resources is:","waste",["income","savings","profit"],"Fraud, waste, and abuse.")
H('492.d.3.E',4,"Actions that are not clearly intentional but are inconsistent with sound practices and cause unnecessary costs are called:","abuse",["fraud","coding","audit"],"Abuse vs fraud.")

# ---- 493 Nursing Leadership ----
H('493.d.1.A',3,"A nurse who holds a two-year degree and passes the NCLEX-PN exam is a licensed:","practical nurse",["nurse practitioner","physician","dentist"],"LPNs complete a practical nursing program.")
H('493.d.1.A',4,"Compared with an LPN, a registered nurse generally has a broader scope of practice and more:","education",["uniforms","vacations","pay stubs"],"RNs complete more schooling.")
H('493.d.1.B',3,"A student can become a registered nurse by earning an associate degree in nursing or a bachelor's degree in nursing, abbreviated:","BSN",["MBA","JD","PhD"],"BSN.")
H('493.d.1.B',4,"After completing a nursing program, a graduate must pass the national licensing exam called the:","NCLEX-RN",["SAT","ACT","GRE"],"RN exam.")
H('493.d.1.C',3,"A nurse who has a master's degree and provides primary care, diagnoses, and prescribes medicine is a nurse:","practitioner",["aide","orderly","technician"],"NPs are advanced practice.")
H('493.d.1.C',4,"A nurse anesthetist is an advanced practice nurse who specializes in giving:","anesthesia",["haircuts","meals","tours"],"CRNA.")
H('493.d.1.D',3,"A nurse who earns a PhD usually focuses on conducting:","research",["billing","cooking","driving"],"PhD = research.")
H('493.d.1.D',4,"The Doctor of Nursing Practice degree focuses mainly on advanced clinical practice and:","leadership",["art history","poetry","mathematics only"],"DNP.")
H('493.d.1.E',3,"A six-year career plan in nursing might start with an associate degree, followed by working as an RN, and then earning a:","BSN",["high school diploma","GED","driver's license"],"Plan steps.")
H('493.d.1.E',4,"A good career plan lists short-term goals, long-term goals, and the steps needed to reach each, which are called:","milestones",["rumors","menus","slogans"],"Milestones.")
H('493.d.2.A',3,"The nursing hierarchy places a nurse manager above the staff nurse and the nurse aide, forming a chain of:","command",["pay","hobbies","tests"],"Hierarchy.")
H('493.d.2.A',4,"A chief nursing officer is at the top of the nursing hierarchy and reports to the hospital's:","executive leadership",["patients","visitors","vendors"],"CNO.")
H('493.d.2.B',3,"A critical skill for a charge nurse who assigns patients to nurses is:","delegation",["cooking","painting","dancing"],"Delegation.")
H('493.d.2.B',4,"A competency expected of every nurse at all levels is the ability to follow safe, evidence-based:","practice",["recipes","routes","dress codes"],"Core competency.")
H('493.d.2.C',3,"Nurse aides provide basic care such as bathing and feeding, which supports the work of:","registered nurses",["accountants","drivers","chefs"],"Support roles.")
H('493.d.2.C',4,"When each level of the hierarchy performs its role well, patient:","safety improves",["wait gets longer","cost doubles","care ends"],"Impact of roles.")
H('493.d.2.D',3,"A leader who makes decisions alone without input from the team uses an autocratic leadership:","style",["flavor","tool","song"],"Autocratic style.")
H('493.d.2.D',4,"A leader who involves the team in making decisions is using a democratic or participative:","leadership style",["punishment","reward system","scheduling tool"],"Participative style.")
H('493.d.3.A',3,"Writing in a journal about what went well and what could improve at work is a practice of self-:","reflection",["promotion","deception","punishment"],"Self-reflection.")
H('493.d.3.A',4,"Setting aside time for exercise, sleep, and hobbies to avoid burnout is a personal growth practice called self-:","care",["blame","doubt","delay"],"Self-care.")
H('493.d.3.B',3,"Understanding and sharing a patient's feelings is the intrapersonal skill of:","empathy",["rivalry","pride","delay"],"Empathy.")
H('493.d.3.B',4,"Remaining calm while waiting for a slow test result shows the skill of:","patience",["impulsivity","anger","avoidance"],"Patience.")
H('493.d.3.C',3,"A nurse who honors the principle of honesty with a patient is demonstrating professional:","ethics",["fashion","luck","speed"],"Ethics.")
H('493.d.3.C',4,"Respect for patient privacy is a professional value that is also required by the law called:","HIPAA",["OSHA","ADA","FERPA"],"HIPAA.")
H('493.d.3.D',3,"An experienced nurse who helps a new graduate learn the unit's routines is acting as a:","mentor",["rival","patient","visitor"],"Mentoring.")
H('493.d.3.D',4,"A coaching plan for a new nurse should include goals, regular check-ins, and constructive:","feedback",["gossip","punishment","isolation"],"Coaching.")
H('493.d.3.E',3,"Handing a task to another team member while keeping responsibility for the outcome is:","delegation",["avoidance","abandonment","competition"],"Delegation.")
H('493.d.3.E',4,"When a nurse breaks a problem into steps, considers options, and chooses the best solution, the nurse is using:","problem-solving",["guessing","hesitation","denial"],"Decision-making process.")
H('493.d.4.A',3,"For a urgent change in a patient's condition, the best communication method is typically a direct phone call or:","face-to-face report",["a postcard","a social media post","an email next week"],"Urgent matters need immediate contact.")
H('493.d.4.A',4,"A nurse should avoid sending patient names through unsecured text message because it could violate:","privacy rules",["traffic laws","dress codes","parking rules"],"Platform choice.")
H('493.d.4.B',3,"A tool used to communicate patient information between shifts in a structured way is the SBAR, which stands for Situation, Background, Assessment, and:","Recommendation",["Reaction","Rumor","Record"],"SBAR.")
H('493.d.4.B',4,"In writing a patient note, a nurse should be accurate, timely, and:","objective",["opinionated","vague","emotional"],"Charting.")
H('493.d.4.C',3,"For an emergent change such as a patient who stops breathing, the nurse should immediately call a:","rapid response or code team",["supply clerk","billing office","parking attendant"],"Emergency.")
H('493.d.4.C',4,"A routine question about a medication schedule is best handled through a non-urgent method like a message in the:","electronic health record",["emergency call","overhead page","shouted request"],"Routine matter.")
H('493.d.4.D',3,"When a supervisor offers feedback about a mistake, the best response is to listen and ask how to:","improve",["argue","ignore","hide"],"Receiving feedback.")
H('493.d.4.D',4,"When giving constructive criticism, a nurse should be specific, respectful, and focused on the:","behavior",["person's appearance","person's family","past mistakes"],"Giving feedback.")
H('493.d.5.A',3,"A daily agenda that lists tasks in order of importance helps a nurse to:","prioritize",["relax","procrastinate","forget"],"Prioritizing.")
H('493.d.5.A',4,"Using the ABCs of airway, breathing, and circulation helps a nurse decide which task to do:","first",["last","never","later"],"ABC priority.")
H('493.d.5.B',3,"A goal such as earning a certification within a year supports a nurse's professional:","growth",["rumors","delays","costs"],"Professional goals.")
H('493.d.5.B',4,"A goal that is specific, measurable, achievable, relevant, and time-bound is called a:","SMART goal",["vague wish","rough idea","random task"],"SMART.")
H('493.d.5.C',3,"Interruptions, a cluttered workspace, and checking a phone often are factors that waste:","time",["money","food","equipment"],"Time wasters.")
H('493.d.5.C',4,"A strategy to improve time use is to group similar tasks together, such as giving all medications at one:","scheduled round",["random moment","day's end","patient request"],"Batching.")
H('493.d.5.D',3,"Finishing a certification course in one year is a short-term goal, while becoming a nurse manager in ten years is a:","long-term goal",["daily task","hobby","vacation"],"Goal horizons.")
H('493.d.5.D',4,"To balance work and personal goals, a nurse can use a calendar to schedule work shifts, study time, and:","rest",["gossip","delay","errors"],"Balance.")
H('493.d.6.A',3,"An interdisciplinary team in a hospital might include a nurse, a physician, a social worker, and a:","physical therapist",["tourist","accountant","architect"],"Interdisciplinary.")
H('493.d.6.A',4,"The purpose of an interdisciplinary team is to coordinate care so that the patient's needs are met by the combined skills of:","several professions",["one profession","no one","the patient only"],"Collaborative care.")
H('493.d.6.B',3,"Activities done to help team members get to know each other and work together better are called team-:","building exercises",["breaking tasks","dividing games","ending rules"],"Team building.")
H('493.d.6.B',4,"A plan for creating a strong team should include clear roles, shared goals, and open:","communication",["silence","secrets","rivalry"],"Team plan.")
H('493.d.6.C',3,"Two nurses disagree about the best way to handle a task. A positive way to manage the conflict is to listen to each other and focus on the:","problem",["person","past","blame"],"Conflict management.")
H('493.d.6.C',4,"When a conflict cannot be solved between two coworkers, they can ask a neutral third party, such as a supervisor, to help with:","mediation",["punishment","competition","gossip"],"Mediation.")
H('493.d.6.D',3,"Tuckman's stages of team development are forming, storming, norming, and:","performing",["quitting","sleeping","hiding"],"Tuckman.")
H('493.d.6.D',4,"The stage when team members disagree and compete for roles is called:","storming",["forming","norming","adjourning"],"Storming.")
H('493.d.7.A',3,"The state agency that licenses nurses and enforces the practice act for the profession is the Board of:","Nursing",["Education","Health Fitness","Commerce"],"BON.")
H('493.d.7.A',4,"The Board of Nursing can discipline a nurse who violates the Nursing Practice Act by suspending or revoking the nurse's:","license",["uniform","parking permit","lunch break"],"Discipline.")
H('493.d.7.B',3,"A local health department is an example of a(n):","public health agency",["private store","sports team","bank"],"Agencies.")
H('493.d.7.B',4,"The federal agency that enforces workplace safety rules for nurses, such as protection from needlesticks, is:","OSHA",["FDA","CDC","DEA"],"OSHA.")
H('493.d.7.C',3,"The tasks and actions that a nurse is legally allowed to perform based on education and licensure are the nursing scope of:","practice",["luck","rest","display"],"Scope.")
H('493.d.7.C',4,"A nurse who is asked to do a task outside their scope of practice should:","decline and tell the supervisor",["do it anyway","guess","ignore the request silently"],"Stay within scope.")
H('493.d.7.D',3,"A document that shows a nurse has met the legal requirements to practice is a:","license",["certificate of attendance","badge","résumé"],"Licensure is legal.")
H('493.d.7.D',4,"A voluntary credential that shows expertise in a specialty, such as critical care, is a:","certification",["license","diploma","permit"],"Certification is voluntary.")
H('493.d.7.E',3,"The Board of Nursing regulates practice to protect the public, while a professional nursing organization mainly promotes the:","interests of nurses",["interests of the government","price of drugs","building codes"],"Roles differ.")
H('493.d.7.E',4,"Joining a professional nursing organization such as the American Nurses Association provides networking and:","continuing education",["parking","uniforms","coupons"],"Organization benefits.")

B.balance()
